import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Service.css';

const Service = () => {
    const [servicePage, setServicePage] = useState(null);

    useEffect(() => {
        fetch('http://localhost:3001/pages/6', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({})
        })
            .then(response => response.json())
            .then(page => setServicePage(page))
            .catch(error => console.error('Error fetching data:', error));
    }, []);

    const handleSendLocation = () => {
        fetch('http://localhost:3001/api/trackimo/send-location', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ deviceId: '362279607/8621' }) // device ID שלך
        })
            .then(response => response.json())
            .then(data => {
                if (data.error) {
                    console.error('Error:', data.error);
                } else {
                    console.log('Success:', data.message);
                }
            })
            .catch(error => console.error('Error:', error));
    };

    if (!servicePage) return <div>PAGE NOT FOUND</div>;
    const contentService = servicePage.content;

    return (
        <div className="container">
            <div className="image-section"></div>
            <div className="paw"></div>
            <div className="content-section">
                <p className="Hello">{contentService[0]}</p>
                <p className="Miss">{contentService[1]}</p>
                <button className="location" onClick={handleSendLocation}>Send Pet Location</button>
                <button className="location">
                    <Link to="/map">Pet's Location</Link>
                </button>
            </div>
        </div>
    );
};

export default Service;
